// Parity-checking function (even parity, 9-bit data -> bit 8 is parity).
function [8:0] parity;
    input [7:0] data;
    reg [7:0] i;
    reg par;
    begin
        par = 1'b0;
        for (i = 0; i < 8; i = i + 1)
            par = par ^ data[i];
        parity = {par, data};
    end
endfunction

